"""Detail lookups by id or by slug (generated by Shikshya, P1b.6 R2). A page may link to /books/12 or to
/books/the-hobbit; both reach the same row. The slug is tried first, so a slug made only of digits (a book called
1984) still finds its row; the ViewSet's own queryset and permissions still decide who may see it."""
from django.http import Http404


class IdOrSlugLookupMixin:
    def get_object(self):
        queryset = self.filter_queryset(self.get_queryset())
        value = str(self.kwargs.get(self.lookup_url_kwarg or self.lookup_field, ""))
        field = self.lookup_field if self.lookup_field not in ("pk", "id") else "slug"
        names = {f.name for f in queryset.model._meta.fields}
        row = queryset.filter(**{field: value}).first() if field in names else None
        if row is None and value.isdigit():
            row = queryset.filter(pk=int(value)).first()
        if row is None:
            raise Http404
        self.check_object_permissions(self.request, row)
        return row
